import heapq
from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[v].append((u, w))

        dist = [float("inf")] * n
        dist[0] = 0
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue

            for v, w in adj[u]:
                nd = max(d, w)
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))

        ans = max(dist)
        return -1 if ans == float("inf") else ans
